changeSet.sql:
ALTER TABLE zc_cohort
  ADD CONSTRAINT fk_zc_cohort_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_cohort
  ADD CONSTRAINT fk_zc_cohort_programme_version FOREIGN KEY (tenant_id, programme_version_id)
    REFERENCES zc_programme_version (tenant_id, id);

ALTER TABLE zc_cohort_run
  ADD CONSTRAINT fk_zc_cohort_run_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_cohort_run
  ADD CONSTRAINT fk_zc_cohort_run_cohort FOREIGN KEY (tenant_id, cohort_id)
    REFERENCES zc_cohort (tenant_id, id);

ALTER TABLE zc_cohort_membership
  ADD CONSTRAINT fk_zc_cohort_membership_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_cohort_membership
  ADD CONSTRAINT fk_zc_cohort_membership_cohort FOREIGN KEY (tenant_id, cohort_id)
    REFERENCES zc_cohort (tenant_id, id);
ALTER TABLE zc_cohort_membership
  ADD CONSTRAINT fk_zc_cohort_membership_member FOREIGN KEY (tenant_id, member_id)
    REFERENCES zc_member_reference (tenant_id, id);
-- Run must belong to the same cohort.
ALTER TABLE zc_cohort_membership
  ADD CONSTRAINT fk_zc_cohort_membership_cohort_run FOREIGN KEY (tenant_id, cohort_run_id, cohort_id)
    REFERENCES zc_cohort_run (tenant_id, id, cohort_id);

-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_cohort ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_cohort FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_cohort_tenant ON zc_cohort
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_cohort_run ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_cohort_run FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_cohort_run_tenant ON zc_cohort_run
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_cohort_membership ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_cohort_membership FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_cohort_membership_tenant ON zc_cohort_membership
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_cohort_tenant ON zc_cohort;
ALTER TABLE zc_cohort NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_cohort DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_cohort_run_tenant ON zc_cohort_run;
ALTER TABLE zc_cohort_run NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_cohort_run DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_cohort_membership_tenant ON zc_cohort_membership;
ALTER TABLE zc_cohort_membership NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_cohort_membership DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_cohort TO zc_app;
GRANT USAGE ON SEQUENCE zc_cohort_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_cohort_run TO zc_app;
GRANT USAGE ON SEQUENCE zc_cohort_run_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_cohort_membership TO zc_app;
GRANT USAGE ON SEQUENCE zc_cohort_membership_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_cohort FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_cohort_id_seq FROM zc_app;
REVOKE ALL ON zc_cohort_run FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_cohort_run_id_seq FROM zc_app;
REVOKE ALL ON zc_cohort_membership FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_cohort_membership_id_seq FROM zc_app;
